// 北海道: 「令和９年度（2027年度）公立高等学校入学者選抜における学校裁量についての
// 実施予定一覧表」（北海道教育委員会・2026-06-15公表・札幌市立・知内町立・奥尻町立・音威子府村立・
// 三笠市立・大空町立・浜中町立・ニセコ町立を除く道立高校対象・全10頁）。学校・学科ごとに
// 「推薦入学者選抜」（入学枠%・面接・面接以外に実施する項目・個人調査書の評価対象項目）と
// 「一般入学者選抜」（学力検査の傾斜配点・面接・複数尺度による選抜=学力検査重視/調査書重視の
// 2グループの比率と重視項目）が横並びの列で構成される密なマトリクス表。
//
// 一次ソース: `https://www.dokyoi.pref.hokkaido.lg.jp/fs/1/3/1/6/0/1/1/6/_/R9jisshiyotei.pdf`
// (道教委『高等学校入学者選抜情報』ページ`/hk/gks/koukounyuusenn.html`からリンク・Excel由来PDF)。
//
// ★2026-09-21 令和9年度版へ全面置換(旧=令和8年度・2校8レコードのみだった)。抽出は PyMuPDF
// `page.find_tables()` で表のセル(○の列位置)を取得し、ヘッダ行の『入学枠』列を基準に固定オフセットで
// 各項目へ対応付けた(28列版[頁2・頁5・頁7-9]と27列版[頁3・頁4・頁6・頁10]の両方で同じ相対位置=
// ops/baselines/hokkaido-r9/parse.py・gen.py)。頁2の画像目視で列対応(岩見沢東/月形/滝川ほか)を確認。
// 305学科(192校)→推薦入学者選抜266+一般入学者選抜305=571レコード。
//
// ★旧レコード(令和8年度)の誤りの発見: 旧DBの岩見沢東は『調査書重視グループ=評定10:学力0・学力重視
// グループ=学力6:評定4』としていたが、令和9年度の表の列見出しは『学力検査の成績を重視=学力:評定』
// (岩見沢東10:0)・『個人調査書等を重視=評定:学力』(6:4)であり、旧記述は2グループの割当が逆だった
// 可能性が高い(令和8年度PDFは表が転置されていたため読み違えたとみられる)。本ファイルは令和9年度の
// 列見出しどおりに転記している。
//
// selectionCategoryは「推薦入学者選抜」「一般入学者選抜」の2区分。推薦の入学枠に『*』が付く数字は
// 募集人員から連携型入学者選抜による合格内定者数を減じた数のうちの推薦の範囲(鵡川/上川/湧別/鹿追/
// 広尾/羅臼)。推薦入学者選抜では全学科で面接が実施される(表の凡例)。一般入学者選抜の定員は
// 学力検査重視/個人調査書重視/両者を同等に見る定員の3グループに分かれ、標準例は15%/15%/70%
// (各校の配分%は資料に記載なし)。学校名・学科名の表記は6月発表の公立高等学校配置計画案に基づく。
// 注)今後発表される公立高等学校配置計画や市町村教育委員会の決定などにより変更されることがある。

